import XCTest

@testable import CodeConnect
@testable import CodeConnectKit

/// **A start picks the model the agent offers (minor 33), against the daemon's own bytes.**
///
/// `minor-33-wire.json` is what ccd emits (`fixtures/claude/minor-33-wire.json`, regenerated by ccd's test and
/// copied here byte for byte): a `projects` frame whose agents carry their models, in their own words, and whether
/// they are signed in; and a `start_session` that names one. What the menu offers, and every word it adds, are
/// `StartContext`'s, the one source both apps read.
@MainActor
final class Minor33WireTests: XCTestCase {

    // MARK: Harness

    private func wire(_ name: String) throws -> [String: JSONValue] {
        let url = try XCTUnwrap(Bundle(for: type(of: self)).url(forResource: name, withExtension: "json"))
        return try XCTUnwrap(try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue)
    }

    /// The recorded `projects` frame, with Claude Code's `signed_in` and models changed where a case needs it.
    private func projects(claudeSignedIn: Bool? = nil, claudeModels: [JSONValue]? = nil) throws -> ServerMessage {
        var frame = try XCTUnwrap(try wire("minor-33-wire")["projects"]?.objectValue)
        var agents = try XCTUnwrap(frame["agents"]?.arrayValue)
        var claude = try XCTUnwrap(agents[0].objectValue)
        XCTAssertEqual(claude["agent"], .string("claude"))
        if let claudeSignedIn { claude["signed_in"] = .bool(claudeSignedIn) }
        if let claudeModels { claude["models"] = .array(claudeModels) }
        agents[0] = .object(claude)
        frame["agents"] = .array(agents)
        return try JSONDecoder().decode(ServerMessage.self, from: Data(JSONValue.object(frame).canonicalJSONString.utf8))
    }

    private final class Sent {
        var messages: [ClientMessage] = []
    }

    /// A computer at `minor` that has answered with `frame`, and the messages sent to it.
    private func context(_ frame: ServerMessage, minor: UInt32 = 33) throws -> (StartContext, Sent) {
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("minor33-\(UUID().uuidString)")
        addTeardownBlock { try? FileManager.default.removeItem(at: root) }
        let model = AppModel(
            cache: EventCache(root: root),
            codexSpentLedger: CodexSpentLedger(defaults: UserDefaults(suiteName: "cc.tests.\(UUID().uuidString)")!))
        let advertised = try XCTUnwrap(try wire("minor-28-wire")["hello_ack_capabilities"])
        model.connection.simulateConnectedForTesting()
        model.connection.simulateCapabilitiesForTesting(
            try JSONDecoder().decode(Capabilities.self, from: Data(advertised.canonicalJSONString.utf8)), minor: minor)
        let sent = Sent()
        model.connection.sendStub = { message in MainActor.assumeIsolated { sent.messages.append(message) } }
        addTeardownBlock { @MainActor in model.scenePhaseChanged(to: .background) }
        model.connection.injectForTesting(frame)
        return (StartContext(model: model), sent)
    }

    // MARK: The wire

    func testEachAgentsModelsAndSignInDecodeAsSent() throws {
        guard case .projects(_, let agents) = try projects() else { return XCTFail("not a projects frame") }
        let claude = try XCTUnwrap(agents.first { $0.agent == .claude })
        XCTAssertEqual(claude.signedIn, false)
        XCTAssertEqual(claude.models.map(\.value), ["default", "opus", "fable", "sonnet", "haiku"])
        XCTAssertEqual(claude.models.first?.label, "Default (recommended)")
        XCTAssertEqual(
            claude.models.first?.detail, "Use the default model (currently Opus 5.5) · $4/$20 per Mtok")
        let codex = try XCTUnwrap(agents.first { $0.agent == .codex })
        XCTAssertEqual(codex.signedIn, true)
        XCTAssertEqual(codex.models.count, 9)
        XCTAssertEqual(codex.models.first?.label, "GPT-6.1-Sol")
        XCTAssertEqual(codex.models.first?.detail, "Latest workhorse model for coding and everyday work.")
    }

    /// The start the menu sends is the daemon's own `start_session`, byte for byte, model included.
    func testAPickedModelIsSentAsTheDaemonReadsIt() async throws {
        let expected = try XCTUnwrap(try wire("minor-33-wire")["start_session_request"])
        let (context, sent) = try context(try projects(claudeSignedIn: true))
        let haiku = try XCTUnwrap(context.modelChoices.first { $0.agent == .claude && $0.model == "haiku" })
        let project = StartProject(
            path: "/tmp/ccd-minor-33/app", name: "app", lastUsed: Date(), lastAgent: .claude, gitBranch: "main",
            exists: true)
        let id = context.start(project, agent: haiku.agent, model: haiku.model, prompt: "fix the tests")
        for _ in 0..<5 { await Task.yield() }
        let start = try XCTUnwrap(sent.messages.last)
        var encoded = try JSONDecoder().decode(JSONValue.self, from: JSONEncoder().encode(start)).objectValue ?? [:]
        XCTAssertEqual(encoded["request_id"], .string(id))
        encoded["request_id"] = .string("r1")
        XCTAssertEqual(.object(encoded), expected)
    }

    // MARK: The menu

    func testEachAgentOffersItsOwnModelsWithDefaultFirst() throws {
        let (context, _) = try context(try projects(claudeSignedIn: true))
        guard case .choices(let claude) = context.models(.claude) else { return XCTFail("no Claude Code models") }
        XCTAssertEqual(claude.map(\.model), ["default", "opus", "fable", "sonnet", "haiku"], "its own Default, once")
        XCTAssertEqual(claude.map(\.label), ["Default (recommended)", "Opus", "Fable", "Sonnet", "Haiku"])
        XCTAssertTrue(claude[0].isDefault)
        guard case .choices(let codex) = context.models(.codex) else { return XCTFail("no Codex models") }
        XCTAssertEqual(codex.first?.model, nil, "Codex lists no default: Default names no model")
        XCTAssertEqual(codex.first?.label, "Default")
        XCTAssertEqual(codex.dropFirst().map(\.model).first, "gpt-6.1-sol")
        XCTAssertEqual(codex.count, 10)
    }

    func testTheButtonAndTheBarSayWhatStartDoes() throws {
        let (context, _) = try context(try projects(claudeSignedIn: true))
        let claude = context.modelChoices.filter { $0.agent == .claude }
        XCTAssertEqual(context.title(claude[0]), "Claude Code · Default")
        XCTAssertEqual(StartContext.starts(claude[0]), "Starts Claude Code with its default model.")
        XCTAssertEqual(context.title(claude[1]), "Claude Code · Opus")
        XCTAssertEqual(StartContext.starts(claude[1]), "Starts Claude Code with Opus.")
        let codexDefault = try XCTUnwrap(context.modelChoices.first { $0.agent == .codex })
        XCTAssertEqual(context.title(codexDefault), "Codex · Default")
        XCTAssertEqual(StartContext.starts(codexDefault), "Starts Codex with its default model.")
    }

    /// The recorded frame as sent: Claude Code is signed out, so it offers how to sign in, and the start opens on
    /// Codex's Default even in a folder Claude Code used last.
    func testASignedOutAgentOffersOnlyHowToSignIn() throws {
        let (context, _) = try context(try projects())
        XCTAssertEqual(context.models(.claude), .signedOut("Sign in to Claude Code on this computer to use it."))
        XCTAssertFalse(context.modelChoices.contains { $0.agent == .claude })
        let folder = StartProject(
            path: "/tmp/ccd-minor-33/app", name: "app", lastUsed: Date(), lastAgent: .claude, gitBranch: "main",
            exists: true)
        let opening = try XCTUnwrap(context.defaultChoice(for: folder))
        XCTAssertEqual(opening.agent, .codex)
        XCTAssertNil(opening.model)
    }

    /// No models listed: an older computer offers the agent alone, with the line that says why; a newer one,
    /// whose agent couldn't be asked, offers Default alone.
    func testNoModelsListedOffersTheAgentAloneOnAnOlderComputerAndDefaultOnANewerOne() throws {
        let unasked = try projects(claudeSignedIn: true, claudeModels: [])
        let (older, _) = try context(unasked, minor: 32)
        XCTAssertEqual(older.models(.claude), .agentOnly)
        XCTAssertEqual(older.title(try XCTUnwrap(older.modelChoices.first { $0.agent == .claude })), "Claude Code")
        XCTAssertEqual(StartContext.updateForModels, "Update CodeConnect on this computer to choose a model.")
        let (newer, _) = try context(unasked, minor: 33)
        guard case .choices(let claude) = newer.models(.claude) else { return XCTFail("no Default") }
        XCTAssertEqual(claude.map(\.label), ["Default"])
        XCTAssertNil(claude[0].model)
    }
}
